def all_aligned_dynamic(grid, maxdist=None, order='short'):
 h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]; fg=next(v for row in grid for v in row if v!=bg); out=[row[:] for row in grid]
 # each candidate segment from consecutive original fg points aligned
 edges=[]
 for r in range(h):
  inds=[c for c in range(w) if grid[r][c]==fg]
  for a,b in zip(inds,inds[1:]):edges.append((b-a,(r,a),(r,b)))
 for c in range(w):
  inds=[r for r in range(h) if grid[r][c]==fg]
  for a,b in zip(inds,inds[1:]):edges.append((b-a,(a,c),(b,c)))
 if order=='short': edges.sort()
 elif order=='long':edges.sort(reverse=True)
 def compid():
  seen={}; idx=0
  for r in range(h):
   for c in range(w):
    if out[r][c]!=fg or (r,c) in seen:continue
    todo=[(r,c)];seen[(r,c)]=idx
    for y,x in todo:
     for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
      p=(y+dy,x+dx)
      if 0<=p[0]<h and 0<=p[1]<w and out[p[0]][p[1]]==fg and p not in seen:seen[p]=idx;todo.append(p)
    idx+=1
  return seen
 for d,(r,c),(rr,cc) in edges:
  if maxdist is not None and d>maxdist:continue
  ids=compid()
  if ids[(r,c)]==ids[(rr,cc)]:continue
  if r==rr:
   for x in range(min(c,cc)+1,max(c,cc)):
    if out[r][x]==bg:out[r][x]=2
  else:
   for y in range(min(r,rr)+1,max(r,rr)):
    if out[y][c]==bg:out[y][c]=2
 return out
